import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { KASessionVerificationPage } from './ka-session-verification.page';

const routes: Routes = [
  {
    path: '',
    component: KASessionVerificationPage
  },
  {
    path: 'arp-course-materials',
    loadChildren: () => import('./arp-course-materials/arp-course-materials.module').then( m => m.ArpCourseMaterialsPageModule)
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class KASessionVerificationPageRoutingModule {}
